\begin{tikzpicture}[line cap=round,line join=round,font=\sffamily\small]
% cell
\draw[thick] (0,0) rectangle (1.1,0.65);
\node at (0.55,0.32) {cell};
\node[font=\bfseries] at (-0.25,0.32) {$-$};
\node[font=\bfseries] at (1.35,0.32) {$+$};
% wires
\draw[thick] (1.1,0.32) -- (1.9,0.32) -- (1.9,1.55);
\draw[thick] (0,0.32) -- (-0.55,0.32) -- (-0.55,1.55) -- (1.9,1.55);
% iron nail
\draw[thick,fill=gray!30] (2.1,1.3) rectangle (5.1,1.8);
\node at (3.6,2.1) {iron nail};
% coil
\foreach \x in {2.35,2.65,2.95,3.25,3.55,3.85,4.15,4.45} {
  \draw[thick] (\x,1.2) arc (240:-60:0.2 and 0.4);
}
\node at (3.6,0.8) {coil};
% clips
\draw[thick] (5.15,1.4) -- (5.55,1.2) -- (5.55,1.6) -- cycle;
\draw[thick] (5.15,1.65) -- (5.5,1.5) -- (5.5,1.85) -- cycle;
\node at (6.05,1.5) {clips};
\end{tikzpicture}
